import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Owasp","description":"Owasp reference documentation","frontmatter":{"title":"Owasp","description":"Owasp reference documentation"},"headers":[],"relativePath":"knowledge/owasp.md","filePath":"knowledge/owasp.md","lastUpdated":1784485118000}'),s={name:"knowledge/owasp.md"};function n(o,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="owasp" tabindex="-1">Owasp <a class="header-anchor" href="#owasp" aria-label="Permalink to &quot;Owasp&quot;">​</a></h1><h1 id="owasp-top-10-2021-—-security-knowledge" tabindex="-1">OWASP Top 10 2021 — Security Knowledge <a class="header-anchor" href="#owasp-top-10-2021-—-security-knowledge" aria-label="Permalink to &quot;OWASP Top 10 2021 — Security Knowledge&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The OWASP Top 10 is the standard awareness document for web application security. It represents a broad consensus about the most critical security risks to applications. This knowledge base provides practical guidance for identifying, preventing, and mitigating these vulnerabilities in modern TypeScript/Next.js applications.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="a01-2021-—-broken-access-control" tabindex="-1">A01:2021 — Broken Access Control <a class="header-anchor" href="#a01-2021-—-broken-access-control" aria-label="Permalink to &quot;A01:2021 — Broken Access Control&quot;">​</a></h3><p>Access control enforces policy such that users cannot act outside their intended permissions. Failures typically lead to unauthorized information disclosure, modification, or destruction of data.</p><p><strong>Key principles:</strong></p><ul><li>Deny by default — require explicit grants for every resource</li><li>Implement access control mechanisms once and reuse across the application</li><li>Model access controls should enforce record ownership (users can only access their own data)</li><li>Disable web server directory listing and ensure metadata are not in web roots</li></ul><h3 id="a02-2021-—-cryptographic-failures" tabindex="-1">A02:2021 — Cryptographic Failures <a class="header-anchor" href="#a02-2021-—-cryptographic-failures" aria-label="Permalink to &quot;A02:2021 — Cryptographic Failures&quot;">​</a></h3><p>Formerly &quot;Sensitive Data Exposure.&quot; Focuses on failures related to cryptography that lead to exposure of sensitive data.</p><p><strong>Key areas:</strong></p><ul><li>Classify data processed and identify which is sensitive</li><li>Don&#39;t store sensitive data unnecessarily; discard it as soon as possible</li><li>Encrypt all sensitive data at rest using AES-256-GCM or ChaCha20</li><li>Encrypt data in transit with TLS 1.3 (minimum TLS 1.2)</li><li>Use strong, industry-standard algorithms (AES-GCM, not ECB mode)</li><li>Use proper key management — rotate keys regularly, never commit keys</li></ul><h3 id="a03-2021-—-injection" tabindex="-1">A03:2021 — Injection <a class="header-anchor" href="#a03-2021-—-injection" aria-label="Permalink to &quot;A03:2021 — Injection&quot;">​</a></h3><p>Injection flaws occur when untrusted data is sent to an interpreter as part of a command or query. SQL, NoSQL, OS command, ORM, LDAP, and Expression Language injections are all possible.</p><p><strong>Prevention:</strong></p><ul><li>Use parameterized queries (Supabase client handles this)</li><li>Use ORMs with parameterized query builders (Prisma, Drizzle)</li><li>Validate and sanitize all user input server-side</li><li>Escape special characters in output contexts</li><li>Limit query results to prevent mass data disclosure</li></ul><h3 id="a04-2021-—-insecure-design" tabindex="-1">A04:2021 — Insecure Design <a class="header-anchor" href="#a04-2021-—-insecure-design" aria-label="Permalink to &quot;A04:2021 — Insecure Design&quot;">​</a></h3><p>Focuses on risks related to design and architectural flaws. Calls for more use of threat modeling, secure design patterns, and reference architectures.</p><p><strong>Approach:</strong></p><ul><li>Establish and use a secure development lifecycle</li><li>Integrate security language and controls into user stories</li><li>Integrate plausibility checks at each tier of your application</li><li>Write integration tests that validate all critical flows</li><li>Segment application layers and tiers on the system and network</li></ul><h3 id="a05-2021-—-security-misconfiguration" tabindex="-1">A05:2021 — Security Misconfiguration <a class="header-anchor" href="#a05-2021-—-security-misconfiguration" aria-label="Permalink to &quot;A05:2021 — Security Misconfiguration&quot;">​</a></h3><p>Missing appropriate security hardening across any part of the application stack, improperly configured permissions, or unnecessary features enabled.</p><p><strong>Common issues:</strong></p><ul><li>Missing appropriate security hardening</li><li>Improperly configured permissions on cloud services</li><li>Unnecessary features enabled (ports, services, privileges, accounts)</li><li>Default accounts and passwords still enabled</li><li>Error handling reveals stack traces or overly informative error messages</li><li>Security settings in application frameworks not configured to secure values</li></ul><h3 id="a06-2021-—-vulnerable-and-outdated-components" tabindex="-1">A06:2021 — Vulnerable and Outdated Components <a class="header-anchor" href="#a06-2021-—-vulnerable-and-outdated-components" aria-label="Permalink to &quot;A06:2021 — Vulnerable and Outdated Components&quot;">​</a></h3><p>Using components with known vulnerabilities is a widespread issue. This includes unsupported, outdated, or end-of-life software.</p><p><strong>Prevention:</strong></p><ul><li>Remove unused dependencies, features, files, and documentation</li><li>Continuously inventory component versions (use <code>npm audit</code>, Dependabot)</li><li>Monitor CVE and NVD for vulnerabilities in components</li><li>Only obtain components from official sources over secure links</li><li>Monitor for unmaintained libraries or SaaS dependency</li></ul><h3 id="a07-2021-—-identification-and-authentication-failures" tabindex="-1">A07:2021 — Identification and Authentication Failures <a class="header-anchor" href="#a07-2021-—-identification-and-authentication-failures" aria-label="Permalink to &quot;A07:2021 — Identification and Authentication Failures&quot;">​</a></h3><p>Confirmation of the user&#39;s identity, authentication, and session management is critical to protect against authentication-related attacks.</p><p><strong>Best practices:</strong></p><ul><li>Implement multi-factor authentication to prevent credential stuffing</li><li>Do not ship with default credentials (admin/admin)</li><li>Implement weak password checks (NIST 800-63b guidelines)</li><li>Limit failed login attempts with account lockout</li><li>Use a server-side, secure session manager with high-entropy random session ID</li></ul><h3 id="a08-2021-—-software-and-data-integrity-failures" tabindex="-1">A08:2021 — Software and Data Integrity Failures <a class="header-anchor" href="#a08-2021-—-software-and-data-integrity-failures" aria-label="Permalink to &quot;A08:2021 — Software and Data Integrity Failures&quot;">​</a></h3><p>Relates to code and infrastructure that does not protect against integrity violations, insecure CI/CD pipelines, and auto-update without sufficient integrity verification.</p><p><strong>Key areas:</strong></p><ul><li>Use digital signatures to verify software/data integrity</li><li>Ensure libraries and dependencies are consumed from trusted repositories</li><li>Use a software supply chain security tool (OWASP Dependency-Check, Snyk)</li><li>Ensure CI/CD pipeline has proper segregation and configuration</li><li>Review code and configuration changes with proper segregation</li></ul><h3 id="a09-2021-—-security-logging-and-monitoring-failures" tabindex="-1">A09:2021 — Security Logging and Monitoring Failures <a class="header-anchor" href="#a09-2021-—-security-logging-and-monitoring-failures" aria-label="Permalink to &quot;A09:2021 — Security Logging and Monitoring Failures&quot;">​</a></h3><p>Without sufficient logging and monitoring, breaches cannot be detected. Insufficient logging, detection, monitoring, and active response occurs at the most basic level.</p><p><strong>Requirements:</strong></p><ul><li>Log all login attempts, access control failures, and input validation failures</li><li>Use a format suitable for log management solutions (structured JSON)</li><li>Ensure high-value transactions have an audit trail</li><li>Establish effective monitoring and alerting</li><li>Establish an incident response and recovery plan</li></ul><h3 id="a10-2021-—-server-side-request-forgery-ssrf" tabindex="-1">A10:2021 — Server-Side Request Forgery (SSRF) <a class="header-anchor" href="#a10-2021-—-server-side-request-forgery-ssrf" aria-label="Permalink to &quot;A10:2021 — Server-Side Request Forgery (SSRF)&quot;">​</a></h3><p>SSRF flaws occur when a web application fetches a remote resource without validating the user-supplied URL.</p><p><strong>Prevention:</strong></p><ul><li>Sanitize and validate all client-supplied input data</li><li>Enforce the URL schema, port, and destination with a positive allow list</li><li>Do not send raw responses to clients</li><li>Disable HTTP redirections</li><li>Segment remote resource access functionality in separate networks</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Validate all input server-side</strong> — Never trust client-side validation alone; always revalidate on the server regardless of frontend checks</li><li><strong>Use parameterized queries exclusively</strong> — Supabase client and Prisma both use parameterized queries; never concatenate user input into SQL strings</li><li><strong>Implement Content Security Policy</strong> — Add CSP headers to prevent XSS by restricting which resources can be loaded and from where</li><li><strong>Apply least privilege principle</strong> — Every user, service, and process should have minimum required permissions; use Supabase RLS for row-level security</li><li><strong>Encrypt sensitive data at rest and in transit</strong> — Use AES-256-GCM for data at rest and TLS 1.3 for data in transit; rotate encryption keys periodically</li><li><strong>Log security events</strong> — Record authentication attempts, access control failures, and data modification events in structured JSON format</li><li><strong>Keep dependencies updated</strong> — Run <code>npm audit</code> weekly, use Dependabot or Renovate for automated dependency updates</li><li><strong>Conduct regular security reviews</strong> — Perform threat modeling for new features, code reviews with security focus, and periodic penetration testing</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Storing secrets in source code</strong> — Never commit API keys, passwords, or connection strings to Git; use environment variables and a <code>.env.local</code> file (gitignored)</li><li><strong>Trusting client-side validation</strong> — Frontend validation improves UX but provides zero security; all validation rules must be enforced server-side</li><li><strong>Returning detailed error messages to clients</strong> — Stack traces, database errors, and internal paths leak implementation details; return generic error messages</li><li><strong>Using MD5 or SHA1 for password hashing</strong> — These are not designed for password storage; use bcrypt, scrypt, or Argon2id with appropriate cost factors</li><li><strong>Disabling CORS entirely</strong> — Setting <code>Access-Control-Allow-Origin: *</code> without credentials is permissive; use explicit origin allow lists</li><li><strong>Skipping HTTPS</strong> — Always use HTTPS in production; HTTP allows man-in-the-middle attacks and session hijacking</li><li><strong>Hardcoding role checks in components</strong> — Authorization logic scattered across components is inconsistent and error-prone; centralize in middleware or API layer</li><li><strong>Ignoring npm audit warnings</strong> — Treat <code>npm audit</code> findings as actionable issues; vulnerabilities in dependencies become vulnerabilities in your application</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Exposing Supabase service role key to the client</strong> — <code>SUPABASE_SERVICE_ROLE_KEY</code> must never be in <code>NEXT_PUBLIC_</code> variables; it bypasses RLS and should only be used server-side</li><li><strong>Missing CSRF protection on state-changing routes</strong> — Next.js App Router API routes should validate CSRF tokens or use SameSite cookie attributes</li><li><strong>Leaking API keys through client bundles</strong> — Any key in a <code>NEXT_PUBLIC_</code> variable is embedded in the JavaScript bundle; use server-side API routes for sensitive operations</li><li><strong>Using overly permissive RLS policies</strong> — A policy like <code>true</code> allows all operations; always scope to <code>auth.uid()</code> or specific roles</li><li><strong>Not validating JWT tokens properly</strong> — Verify token signatures, check expiration, and validate issuer/audience claims on every protected route</li><li><strong>Forgetting to sanitize HTML output</strong> — Rich text from users must be sanitized before rendering to prevent stored XSS attacks</li><li><strong>Exposing internal IDs unnecessarily</strong> — Auto-incrementing database IDs leak information; consider using UUIDs for public-facing identifiers</li><li><strong>Running application as root</strong> — Never run production services as root; use a non-privileged user in Docker containers</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Decision</th></tr></thead><tbody><tr><td>User input reaches database</td><td>Always use parameterized queries or ORM</td></tr><tr><td>Storing user passwords</td><td>Use Argon2id (preferred) or bcrypt with cost ≥12</td></tr><tr><td>API authentication</td><td>JWT with short expiry + refresh tokens, or session cookies</td></tr><tr><td>Multi-tenant data access</td><td>Implement Supabase RLS policies per tenant</td></tr><tr><td>File uploads</td><td>Validate file type, size, scan for malware, store outside web root</td></tr><tr><td>Third-party API keys</td><td>Store in environment variables, rotate quarterly</td></tr><tr><td>Sensitive data in logs</td><td>Never log PII, tokens, or passwords; mask sensitive fields</td></tr><tr><td>Error handling</td><td>Catch all errors, log internally, return generic message to client</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>OWASP Top 10 2021: <a href="https://owasp.org/Top10/" target="_blank" rel="noreferrer">https://owasp.org/Top10/</a></li><li>OWASP Application Security Verification Standard (ASVS): <a href="https://owasp.org/www-project-application-security-verification-standard/" target="_blank" rel="noreferrer">https://owasp.org/www-project-application-security-verification-standard/</a></li><li>OWASP Cheat Sheet Series: <a href="https://cheatsheetseries.owasp.org/" target="_blank" rel="noreferrer">https://cheatsheetseries.owasp.org/</a></li><li>NIST Cybersecurity Framework: <a href="https://www.nist.gov/cyberframework" target="_blank" rel="noreferrer">https://www.nist.gov/cyberframework</a></li><li>PortSwigger Web Security Academy: <a href="https://portswigger.net/web-security" target="_blank" rel="noreferrer">https://portswigger.net/web-security</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Next.js specific:</strong> Use <code>middleware.ts</code> for authentication checks at the edge before routes are served</li><li><strong>Supabase specific:</strong> Enable RLS on every table; create policies using <code>auth.uid()</code> and <code>auth.jwt()</code> functions</li><li><strong>Deployment:</strong> Vercel automatically provides HTTPS; ensure security headers are configured in <code>next.config.js</code></li><li><strong>CI/CD:</strong> Add <code>npm audit --audit-level=high</code> to pipeline; block deployment on high-severity findings</li><li><strong>Incident response:</strong> Have a documented process for security incidents including who to notify and how to contain breaches</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',59)])])}const h=t(s,[["render",n]]);export{g as __pageData,h as default};
